import {legacyTag,legacyMechanic,legacyName} from './legacy.mjs';
import * as E from './high-elf.mjs';
import * as M from './rules.mjs';
import {careerAvailable,originProfile} from './origins.mjs';
import {sourceLabel} from './sources.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pick=(label,bind,choices,value='',attrs='')=>`<div class="field"><label>${esc(label)}<select data-bind="${bind}" ${attrs}><option value="">Choose…</option>${choices.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label></div>`;
const button=(action,text,attrs='')=>`<button type="button" class="quiet" data-action="${action}" ${attrs}>${esc(text)}</button>`;
export function elfOriginPanel(R,s){
 if(!E.asur(R,s))return '';
 const e=E.elfState(s),v=R.highElfCreation,era=E.birthEra(R,s),psy=E.bloodPsychology(R,s),sea=originProfile(R,s)?.name==='Sea Elf';
 return `<section class="section-gap"><h2>High Elf background <span class="source">High Elf Guide pp. 47–58</span></h2>${sea?`<div class="notice"><strong>Sea Elf enclave & heritage</strong><p class="small muted">These are background choices; heritage grants no second regional profile.</p><div class="field"><label for="elf-enclave">Home enclave</label><input id="elf-enclave" data-bind="elfText" data-key="enclave" value="${esc(e.enclave)}" list="elf-enclaves" maxlength="100"><datalist id="elf-enclaves">${v.enclaves.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div>${pick('Ulthuan heritage','elfChoice',v.kingdoms,e.heritage,'data-key="heritage"')}</div>`:''}<details data-group="elf-elder" ${era?'open':''}><summary>Age & optional Elder creation · p. 53 ${legacyTag(R,legacyMechanic('elder'))}</summary><p class="small muted">Choose a printed era, or leave this blank for normal core age creation. Earlier eras add 10 chosen or 15 rolled individual Skill points per past Career, at most five per Skill per era. They grant no free Talents, equipment or tracker boxes. The oldest era’s weekly Yenlui Test applies; other burdens accumulate.</p>${pick('Birth era','elfEra',v.eras.map(x=>[x.id,`${x.name} · ${x.min}–${x.max??'∞'} years`]),e.era)}${era?`<div class="field"><label for="elf-age">Age in years</label><input id="elf-age" type="number" min="${era.min}" ${era.max===null?'':`max="${era.max}"`} data-bind="elfAge" value="${e.elderAge??''}"></div>${button('elf-age',`Roll ${era.offset} + ${era.dice[0]}d10`)}<p class="small muted">Printed dice can extend outside the printed age band; exact rolled results are retained with an explanation.</p>${era.id!=='ending'?`<p class="purchase-error small">Proposed Fifth Edition adaptation approved by you: reduce starting Fate or Fortune by one. Time of Shadows sets both to zero; Blood of Aenarion takes priority.</p>${pick('Reduce starting resource','elfChoice',['Fate','Fortune'],e.elderResource,'data-key="elderResource"')}<p class="small">${esc(era.burden)}</p>${E.elderEras(R,s).map(x=>{const h=e.history.find(h=>h.era===x.id),c=R.careers.find(c=>c.id===h.career);return `<div class="notice"><strong>${esc(x.name)} — past Career</strong>${pick('Past Career','elfPastCareer',R.careers.filter(c=>careerAvailable(R,s,c)).map(c=>[c.id,c.name]),h.career,`data-era="${x.id}"`)}${button('elf-past-roll','Roll Career · 15 points',`data-era="${x.id}" ${h.roll?'disabled':''}`)}${h.roll?button('elf-past-retain','Retain recorded Career · 15 points',`data-era="${x.id}"`):''}<p class="small muted">${h.mode==='rolled'?'Rolled Career: 15 individual points.':'Chosen Career: 10 individual points.'} Allocate them in Starting Skills.${h.roll?` Recorded d100 ${h.roll.face}: ${esc(R.careers.find(c=>c.id===h.roll.career)?.name)}.`:''}</p></div>`;}).join('')}`:''}`:''}</details><details data-group="elf-blood" ${E.blood(R,s)?'open':''}><summary>Blood of Aenarion · p. 51 ${legacyTag(R,legacyMechanic('blood'))}</summary><p class="small muted">Optional ancestry. Rolling gives 5% for the Noble Career or Noble Blood Talent; 1% otherwise. You may choose it with your GM. It grants +1 Fate, one Prodigy benefit, and a rolled Psychology using core effects.</p>${pick('Ancestry','elfChoice',[['none','No Blood of Aenarion'],['chosen','Choose ancestry with GM'],...(e.bloodRoll?[['rolled',`Use recorded roll ${e.bloodRoll.face} · ${e.bloodRoll.success?'Blood of Aenarion':'no ancestry'}`]]:[])],e.ancestry,'data-key="ancestry"')}${button('elf-blood','Roll ancestry · d100',e.bloodRoll?'disabled':'')}${E.blood(R,s)?`${pick('Prodigy benefit','elfChoice',[['magic','Magical Prodigy · half spell XP'],['martial','Martial Prodigy · half seven named Talent prices']],e.prodigy,'data-key="prodigy"')}<p class="small muted">Discounts apply only to legal purchases. Ritual memorisation is included in the spell discount by your approved interpretation; Sword-dancing techniques are separate.</p>${button('elf-psychology','Roll Psychology · d100',e.psychology?'disabled':'')}${psy?`<p><strong>${esc(psy.name)}</strong> · ${esc(psy.text)}</p><p class="small muted">Core p. 189 effects; this is Psychology, not a Mutation.</p>`:''}`:''}</details><details data-group="elf-spirituality"><summary>Spirituality, Dream & Obsession · pp. 47–50</summary>${pick('Starting Yenlui state','elfChoice',['Balanced','Light','Dark'],e.yenlui,'data-key="yenlui"')}<p class="small muted">${esc(E.yenluiReference({...s,highElf:{...e,yenlui:e.yenlui||'Balanced'}}))}</p>${['dream','obsession'].map(k=>`<div class="field"><label>${k==='dream'?'Dream':'Obsession'}<textarea data-bind="elfText" data-key="${k}" maxlength="1000">${esc(e[k])}</textarea></label></div>${pick('Book '+(k==='dream'?'Dream':'Obsession')+' suggestion','elfSuggestion',v[k==='dream'?'dreams':'obsessions'].rows.map(x=>[String(x.face),x.face+'. '+x.text]),'',`data-key="${k}"`)}${button('elf-suggestion','Roll '+k+' · d10',`data-key="${k}"`)}`).join('')}</details></section>`;
}
export function elfCareerPanel(R,s){
 if(!E.asur(R,s)||originProfile(R,s)?.source.book!=='high-elf')return '';
 if(s.career==='sailor')return pick('Optional Elven ship Sailor variant · p. 63','elfChoice',[['standard','Core Sailor'],['elven-ship','Elven ship · Legacy · Intuition at L2, remove Alcohol, Brawling → Basic']],E.elfState(s).careerVariant||'standard','data-key="careerVariant"');
 if(s.career==='pit-fighter'&&originProfile(R,s)?.name!=='Sea Elf')return pick('Optional Ulthuan Pit Fighter variant · p. 60','elfChoice',[['standard','Core Dirty Fighting'],['feint','Replace Dirty Fighting with Feint']],E.elfState(s).careerVariant||'standard','data-key="careerVariant"');
 return '';
}
export function elfSkillsPanel(R,s){
 const eras=E.elderEras(R,s);if(!eras.length)return '';
 return `<h2>Elder Skill points ${legacyTag(R,legacyMechanic('elder'))} <span class="source">High Elf Guide p. 53</span></h2><p class="small muted">Individual points are additional to normal creation. Spend the full budget for each past Career; no more than five in the same Skill per era.</p>${eras.map(era=>{const h=E.elfState(s).history.find(h=>h.era===era.id),budget=h.mode==='rolled'?15:10,slots=E.elderSkillSlots(R,s,h);return `<details data-group="elf-skills-${era.id}" open><summary>${esc(era.name)} · ${esc(R.careers.find(c=>c.id===h.career)?.name||'Choose past Career in Origins')} <span class="counter">${Object.values(h.points||{}).reduce((a,b)=>a+b,0)}/${budget}</span></summary>${slots.map(x=>`<div class="skill-row"><div>${x.options.length>1?pick(x.raw,'elfPastSkill',x.options,x.name,`data-era="${era.id}" data-key="${x.key}"`):`<strong>${esc(x.name)}</strong>`}</div><label class="small">Individual points <input type="number" min="0" max="5" step="1" data-bind="elfPastPoints" data-era="${era.id}" data-key="${x.key}" value="${h.points?.[x.key]||0}" aria-label="${esc(era.name+' '+x.name)} points"></label></div>`).join('')}</details>`;}).join('')}`;
}
const description=(R,x)=>`<details><summary>${esc(x.name)} · ${esc(sourceLabel(R,x))}</summary><p class="small">${esc(x.text)}</p>${x.conversion?`<p class="small muted">${esc(x.conversion)}</p>`:''}</details>`;
export function elfMagicShop(R,s,errors=[]){
 if(!E.highElfGuide(R))return '';
 const d=M.derive(R,s),known=M.knownSpells(R,s),tech=E.knownTechniques(R,s);
 const row=(x,q,action)=>{const error=q.error||(errors.length?'Finish creation before spending XP.':'');return `<div class="xp-row">${description(R,x)}<div>${button(action,`${q.cost} XP`,`data-name="${esc(x.name)}" data-talent="${esc(q.talent||'')}" ${error?'disabled':''}`)}${error?`<p class="purchase-error minilabel">${esc(error)}</p>`:''}${q.discount?`<p class="small muted">${esc(q.discount)}</p>`:''}</div></div>`;};
 return `${d.talents.includes('Sword-dancing')?`<h3>Sword-dancing techniques · pp. 68–69</h3><p class="small muted">Ritual of Cleansing is free. Other techniques cost 100 XP per technique already known and earn no tracker boxes.</p>${tech.map(x=>description(R,x)).join('')}${R.techniques.filter(x=>!tech.some(k=>k.name===x.name)).map(x=>row(x,E.quoteTechnique(R,s,x.name),'buy-technique')).join('')}`:''}${(E.asur(R,s)||d.talents.some(x=>M.base(x)==='Arcane Magic'))?['Elven Arcane','High Magic'].map(category=>`<details class="section-gap" data-group="elf-magic-${category}"><summary>${esc(category)} ${legacyTag(R,category==='High Magic'?M.talentInfo(R,'High Magic'):legacyMechanic('elvenArcane'))} · ${R.spells.filter(x=>x.category===category).length} spells</summary><p class="small muted">${category==='High Magic'?'Requires High Magic; no free spell grant. Prices use Intelligence Bonus bands. Fifth Career level and priest branches are deferred.':'Requires both printed Colour Lores; each spell is learned once and belongs to the latest acquired Lore.'}</p>${R.spells.filter(x=>x.category===category&&!known.some(k=>k.name===x.name)).map(x=>row(x,E.quoteElfSpell(R,s,x.name),'buy-spell')).join('')}</details>`).join(''):''}`;
}
export function elfReview(R,s){return E.highElfReferences(R,s).map(x=>`<p class="small muted">${esc(sourceLabel(R,x))}: ${esc(x.text)}</p>`).join('')+E.knownTechniques(R,s).map(x=>description(R,x)).join('');}
export function elfAction(R,s,el,roll){
 const a=el.dataset.action;if(!a.startsWith('elf-'))return false;
 if(s.ledger.length)throw Error('Undo or clear advancement before changing High Elf creation.');
 const e=s.highElf??={};
 if(a==='elf-suggestion'){const key=el.dataset.key,t=R.highElfCreation[key==='dream'?'dreams':'obsessions'];const face=roll(10,t.page,key+' suggestion',{book:'high-elf',page:t.page},1);e[key]=t.rows.find(x=>x.face===face).text;}
 else if(a==='elf-age'){const era=E.birthEra(R,s);if(!era)throw Error('Choose an era first.');e.elderAge=era.offset+roll(10,53,'Elder age',{book:'high-elf',page:53},era.dice[0]);e.ageRolled=true;}
 else if(a==='elf-blood')E.rollBlood(R,s,roll);
 else if(a==='elf-psychology'){if(!E.blood(R,s)||e.psychology)throw Error('Psychology already recorded or ancestry not selected.');e.psychology=roll(100,51,'Aenarion Psychology',{book:'high-elf',page:51},1);}
 else if(a==='elf-past-roll')E.rollElderCareer(R,s,el.dataset.era,roll);
 else if(a==='elf-past-retain'){const h=e.history.find(x=>x.era===el.dataset.era);if(!h?.roll)throw Error('No past Career roll.');Object.assign(h,{career:h.roll.career,mode:'rolled',points:{},choices:{}});}
 else throw Error('Unknown High Elf action.');
 return true;
}
export function elfChange(R,s,el){
 const {bind,key,era}=el.dataset;if(!bind?.startsWith('elf'))return false;
 if(s.ledger.length)throw Error('Undo or clear advancement before changing High Elf creation.');
 const e=s.highElf??={};
 if(bind==='elfEra')E.selectElfEra(R,s,el.value);
 else if(bind==='elfAge'){e.elderAge=Number(el.value);e.ageRolled=false;}
 else if(bind==='elfText')e[key]=el.value;
 else if(bind==='elfChoice')e[key]=el.value;
 else if(bind==='elfSuggestion'){const t=R.highElfCreation[key==='dream'?'dreams':'obsessions'];if(el.value)e[key]=t.rows.find(x=>String(x.face)===el.value).text;}
 else {const h=e.history?.find(x=>x.era===era);if(!h)throw Error('Choose the past era first.');
  if(bind==='elfPastCareer'){Object.assign(h,{career:el.value,mode:'chosen',points:{},choices:{}});}
  else if(bind==='elfPastSkill')h.choices[key]=el.value;
  else if(bind==='elfPastPoints'){const n=Number(el.value);if(!Number.isInteger(n)||n<0||n>5)throw Error('Use 0–5 individual points.');h.points[key]=n;}
  else throw Error('Unknown High Elf field.');
 }
 return true;
}
